import java.io.*;
import java.util.*;

public class Main {
    static final InputStream IN = System.in;
    static final byte[] BUF = new byte[1 << 16];
    static int len, ptr;

    static int readByte() throws IOException {
        if (ptr == len) {
            len = IN.read(BUF, 0, BUF.length);
            ptr = 0;
            if (len <= 0) {
                len = 0;
                return -1;
            }
        }
        return BUF[ptr++];
    }

    static long nextLong() throws IOException {
        int c = readByte();
        while (c == ' ' || c == '\n' || c == '\r' || c == '\t') c = readByte();
        boolean neg = c == '-';
        if (neg) c = readByte();
        long v = 0;
        while (c >= '0' && c <= '9') {
            v = v * 10 + (c - '0');
            c = readByte();
        }
        return neg ? -v : v;
    }

    static int nextInt() throws IOException {
        return (int) nextLong();
    }

    static String next() throws IOException {
        int c = readByte();
        while (c == ' ' || c == '\n' || c == '\r' || c == '\t') c = readByte();
        StringBuilder sb = new StringBuilder();
        while (c > ' ') {
            sb.append((char) c);
            c = readByte();
        }
        return sb.toString();
    }

    static final Set<String> DENOMINATIONS = Set.of("10", "20", "50", "100", "200", "500", "1000");

    static boolean upper(char c) {
        return c >= 'A' && c <= 'Z';
    }

    static long value(String s) {
        int n = s.length();
        if (n < 10 || n > 12) return 0;
        for (int i = 0; i < 3; i++) if (!upper(s.charAt(i))) return 0;
        if (s.charAt(0) == s.charAt(1) || s.charAt(0) == s.charAt(2) || s.charAt(1) == s.charAt(2)) return 0;
        int y = 0;
        for (int i = 3; i < 7; i++) {
            char c = s.charAt(i);
            if (c < '0' || c > '9') return 0;
            y = y * 10 + (c - '0');
        }
        if (y < 1900 || y > 2019) return 0;
        if (!upper(s.charAt(n - 1))) return 0;
        // The denomination is everything between the year and the final letter.
        String v = s.substring(7, n - 1);
        return DENOMINATIONS.contains(v) ? Long.parseLong(v) : 0;
    }

    public static void main(String[] args) throws IOException {
        int n = nextInt();
        long total = 0;
        for (int i = 0; i < n; i++) total += value(next());
        System.out.println(total * 99 / 100);
    }
