package main

import (
	"fmt"
	"io"
	"os"
)

var data []byte
var pos int

// token returns the next whitespace-separated token of stdin.
func token() []byte {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
	start := pos
	for pos < len(data) && data[pos] > ' ' {
		pos++
	}
	return data[start:pos]
}

func nextInt() int {
	b := token()
	neg := len(b) > 0 && b[0] == '-'
	if neg {
		b = b[1:]
	}
	v := 0
	for _, c := range b {
		v = v*10 + int(c-'0')
	}
	if neg {
		return -v
	}
	return v
}

var denominations = map[string]int{"10": 10, "20": 20, "50": 50, "100": 100, "200": 200, "500": 500, "1000": 1000}

func upper(c byte) bool { return c >= 'A' && c <= 'Z' }

// value returns the denomination of a valid serial number and 0 for an invalid one.
func value(s []byte) int {
	n := len(s)
	if n < 10 || n > 12 {
		return 0
	}
	for i := 0; i < 3; i++ {
		if !upper(s[i]) {
			return 0
		}
	}
	if s[0] == s[1] || s[0] == s[2] || s[1] == s[2] {
		return 0
	}
	y := 0
	for i := 3; i < 7; i++ {
		if s[i] < '0' || s[i] > '9' {
			return 0
		}
		y = y*10 + int(s[i]-'0')
	}
	if y < 1900 || y > 2019 || !upper(s[n-1]) {
		return 0
	}
	// The denomination is everything between the year and the final letter.
	return denominations[string(s[7:n-1])]
}

func main() {
	data, _ = io.ReadAll(os.Stdin)
	n := nextInt()
	total := 0
	for i := 0; i < n; i++ {
		total += value(token())
	}
	fmt.Println(total * 99 / 100)
}
